import React from "react";
import {AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig} from "remotion";

export const C = {bg: "#0e0f12", fg: "#f4efe8", mute: "#9a958d", line: "#34363c", acc: "#FFB000"};
export const FONT = "Segoe UI, system-ui, sans-serif";

export const Reveal: React.FC<{delay: number; children: React.ReactNode; style?: React.CSSProperties}> = ({delay, children, style}) => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const e = spring({frame: frame - delay, fps, config: {damping: 200}});
  return <div style={{opacity: e, transform: `translateY(${interpolate(e, [0, 1], [36, 0])}px)`, ...style}}>{children}</div>;
};

export const Frame: React.FC<{step: number; children: React.ReactNode}> = ({step, children}) => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const out = interpolate(frame, [durationInFrames - 12, durationInFrames], [1, 0], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
  return (
    <AbsoluteFill style={{background: C.bg, color: C.fg, fontFamily: FONT, opacity: out}}>
      <div style={{position: "absolute", left: 140, top: 90, display: "flex", gap: 14, alignItems: "center", fontSize: 30, color: C.mute, letterSpacing: 2}}>
        {[1, 2, 3].map((i) => (<div key={i} style={{width: i === step ? 56 : 18, height: 10, borderRadius: 5, background: i === step ? C.acc : C.line}} />))}
        <span style={{marginLeft: 12}}>CAFÉ FILTRE</span>
      </div>
      {children}
    </AbsoluteFill>
  );
};

