import React from "react";
import {interpolate, useCurrentFrame, Easing} from "remotion";
import {C, Frame, Reveal} from "./lib/Kit";

const y = (t: number) => 600 - 5.6 * t;

export default function Scene() {
  const frame = useCurrentFrame();
  const p = interpolate(frame, [15, 85], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic)});
  const top = y(93 * p);
  const band = interpolate(frame, [80, 100], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
  return (
    <Frame step={1}>
      <div style={{position: "absolute", left: 140, top: 300, width: 1000}}>
        <Reveal delay={0}><div style={{fontSize: 40, color: C.mute}}>Le café filtre, en trois gestes</div></Reveal>
        <Reveal delay={8}><h1 style={{fontSize: 190, margin: "10px 0 0", fontWeight: 800}}>L'eau</h1></Reveal>
        <Reveal delay={22}><p style={{fontSize: 60, margin: "20px 0 0", color: C.fg}}>Chaude, pas bouillante.</p></Reveal>
        <Reveal delay={95}><p style={{fontSize: 96, margin: "34px 0 0", color: C.acc, fontWeight: 700}}>90 à 96 °C</p></Reveal>
      </div>
      <svg width={560} height={800} viewBox="0 0 400 800" style={{position: "absolute", right: 220, top: 170}}>
        <rect x={170} y={40} width={60} height={560} rx={30} fill="none" stroke={C.line} strokeWidth={6} />
        <circle cx={200} cy={660} r={80} fill="none" stroke={C.line} strokeWidth={6} />
        <circle cx={200} cy={660} r={68} fill={C.acc} />
        <rect x={182} y={top} width={36} height={640 - top} fill={C.acc} />
        <circle cx={200} cy={top} r={18} fill={C.acc} />
        {[0, 25, 50, 75, 100].map((t) => (<g key={t}><line x1={245} x2={275} y1={y(t)} y2={y(t)} stroke={C.mute} strokeWidth={3} /><text x={290} y={y(t) + 10} fontSize={28} fill={C.mute} fontFamily="Segoe UI, system-ui, sans-serif">{t}</text></g>))}
        <g opacity={band}>
          <path d={`M 140 ${y(96)} L 120 ${y(96)} L 120 ${y(90)} L 140 ${y(90)}`} fill="none" stroke={C.acc} strokeWidth={6} />
        </g>
      </svg>
    </Frame>
  );
}

