import React from "react";
import {interpolate, spring, useCurrentFrame, useVideoConfig} from "remotion";
import {C, Cadre, Reveal} from "./lib/Kit";

const SIZE = 360;

function dots(n: number, r: number) {
  const step = r * 2.5;
  const cols = Math.floor((SIZE - 40) / step);
  const out: {x: number; y: number}[] = [];
  for (let i = 0; i < n; i++) {
    const cx = i % cols;
    const cy = Math.floor(i / cols);
    const rows = Math.ceil(n / cols);
    const inRow = cy === rows - 1 ? n - cy * cols : cols;
    const off = (cols - inRow) * step / 2;
    out.push({
      x: SIZE / 2 - ((cols - 1) * step) / 2 + off + cx * step + Math.sin(i * 7.3) * r * 0.25,
      y: SIZE / 2 - ((rows - 1) * step) / 2 + cy * step + Math.cos(i * 5.1) * r * 0.25,
    });
  }
  return out;
}

const CARDS = [
  {label: "Grosse", n: 4, r: 36, hint: "trop vite"},
  {label: "Moyenne", n: 12, r: 20, hint: "équilibrée"},
  {label: "Fine", n: 42, r: 10, hint: "trop serrée"},
];

export default function Scene() {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  return (
    <Cadre step={2}>
      <div style={{position: "absolute", left: 0, right: 0, top: 200, textAlign: "center"}}>
        <Reveal delay={0}><h1 style={{fontSize: 150, margin: 0, fontWeight: 800}}>La mouture</h1></Reveal>
        <Reveal delay={12}><p style={{fontSize: 52, margin: "8px 0 0", color: C.mute}}>Ni gros éclats, ni poudre.</p></Reveal>
      </div>
      <div style={{position: "absolute", left: 0, right: 0, top: 520, display: "flex", justifyContent: "center", gap: 90}}>
        {CARDS.map((c, k) => {
          const e = spring({frame: frame - (28 + k * 8), fps, config: {damping: 14}});
          const hi = k === 1;
          const focus = interpolate(frame, [70, 90], [0, 1], {extrapolateLeft: "clamp", extrapolateRight: "clamp"});
          const dim = hi ? 1 : 1 - 0.65 * focus;
          const color = hi && focus > 0.5 ? C.acc : C.mute;
          return (
            <div key={c.label} style={{width: SIZE, opacity: e * dim, transform: `scale(${interpolate(e, [0, 1], [0.7, hi ? 1 + 0.06 * focus : 1])})`, textAlign: "center"}}>
              <svg width={SIZE} height={SIZE} style={{border: `4px solid ${hi && focus > 0.5 ? C.acc : C.line}`, borderRadius: 28}}>
                {dots(c.n, c.r).map((d, i) => (<circle key={i} cx={d.x} cy={d.y} r={c.r} fill={color} />))}
              </svg>
              <div style={{fontSize: 52, fontWeight: 700, marginTop: 20, color: hi ? C.fg : C.mute}}>{c.label}</div>
              <div style={{fontSize: 36, color: hi && focus > 0.5 ? C.acc : C.mute}}>{c.hint}</div>
            </div>
          );
        })}
      </div>
    </Cadre>
  );
}

