import React from "react";
import {interpolate, useCurrentFrame, Easing} from "remotion";
import {C, Cadre, Reveal} from "./lib/Kit";

const clamp = {extrapolateLeft: "clamp", extrapolateRight: "clamp"} as const;

export default function Scene() {
  const frame = useCurrentFrame();
  const stream = interpolate(frame, [8, 30], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const fill = interpolate(frame, [40, 125], [0, 150], {...clamp, easing: Easing.inOut(Easing.quad)});
  const drops = [0, 1, 2].map((k) => {
    const t = ((frame - 36 - k * 7) % 21) / 21;
    return frame < 36 ? null : t;
  });
  return (
    <Cadre step={3}>
      <svg width={600} height={800} viewBox="0 0 600 800" style={{position: "absolute", left: 210, top: 200}}>
        <defs><clipPath id="cup"><path d="M 190 560 L 410 560 L 390 730 Q 388 750 368 750 L 232 750 Q 212 750 210 730 Z" /></clipPath></defs>
        <rect x={290} y={0} width={20} height={200 * stream} fill={C.acc} opacity={0.9} />
        <polygon points="60,80 540,80 340,360 260,360" fill="none" stroke={C.fg} strokeWidth={6} strokeLinejoin="round" />
        <polygon points="122,200 478,200 340,360 260,360" fill="#3a3631" />
        {drops.map((t, k) => t === null ? null : (<circle key={k} cx={300} cy={372 + t * 170} r={9} fill={C.acc} opacity={1 - t * 0.3} />))}
        <g clipPath="url(#cup)"><rect x={190} y={750 - fill} width={220} height={fill} fill={C.acc} /></g>
        <path d="M 190 560 L 410 560 L 390 730 Q 388 750 368 750 L 232 750 Q 212 750 210 730 Z" fill="none" stroke={C.fg} strokeWidth={6} />
        <path d="M 410 590 Q 475 590 470 650 Q 465 700 395 705" fill="none" stroke={C.fg} strokeWidth={6} />
      </svg>
      <div style={{position: "absolute", left: 1000, top: 290, width: 780}}>
        <Reveal delay={4}><h1 style={{fontSize: 130, margin: 0, fontWeight: 800}}>L'extraction</h1></Reveal>
        <Reveal delay={24}><p style={{fontSize: 52, margin: "28px 0 0", lineHeight: 1.25}}>L'eau traverse le café et en emporte les arômes.</p></Reveal>
        <Reveal delay={95}><p style={{fontSize: 84, margin: "50px 0 0", color: C.acc, fontWeight: 700}}>Bon café.</p></Reveal>
      </div>
    </Cadre>
  );
}

